n35662.content:
\begin{theorem}
  \label{sum_of_two_squares}
  A natural number \(n\) can be represented as a sum of two squares
  if and only if every prime factor of the form \(p = 4m + 3\) appears with an
  even exponent in the prime decomposition of \(n\).
\end{theorem}

n35663.content:
\begin{proof}
  \uses{ch04.lemma2, ch04.proposition1, ch04.proposition2, ch04.proposition3}
  Call a number $n$ \textit{representable} if it is a sum of two squares, that is, if $n = x^2 + y^2$ for some $x, y \in \mathbb{N}_0$. The theorem is a consequence of the following five facts.
  \begin{enumerate}[label=(\arabic*)]
  	\item $1 = 1^2 + 0^2$ and $2 = 1^2 + 1^2$ are representable. Every prime of the form $p = 4m + 1$ is representable.
  	\item The product of any two representable numbers $n_1 = x_1^2 + y_1^2$ and $n_2 = x_2^2 + y_2^2$ is representable: $n_1 n_2 = (x_1 x_2 + y_1 y_2)^2 + (x_1 y_2 - x_2 y_1)^2$.
  	\item If $n$ is representable, $n = x^2 + y^2$, then also $nz^2$ is representable, by $nz^2 = (xz)^2 + (yz)^2$.
  \end{enumerate}
  Facts (1), (2) and (3) together yield the ``if'' part of the theorem.
  \begin{enumerate}[start=4,label=(\arabic*)]
  	\item If $p = 4m + 3$ is a prime that divides a representable number $n = x^2 + y^2$, then $p$ divides both $x$ and $y$, and thus $p^2$ divides $n$. In fact, if we had $x \not\equiv 0 \pmod{p}$, then we could find $\overline{x}$ such that $x\overline{x} \equiv 1 \pmod{p}$, multiply the equation $x^2 + y^2 \equiv 0$ by $\overline{x}^2$, and thus we would obtain that $1 + y^2 \overline{x}^2 = 1 + \left(\overline{x} y\right)^2 \equiv 0 \pmod{p}$, which is impossible for $p = 4m + 3$ by Lemma 1.
  	\item If $n$ is representable, and $p = 4m + 3$ divides $n$, then $p^2$ divides $n$, and $n/p^2$ is representable. This follows from (4), and completes the proof. \qedhere
  \end{enumerate}
\end{proof}

n35665.content:
\begin{proof}
  Since $\mathbb{Z}_p^* = \mathbb{Z}_p \setminus \{0\}$ is a group with multiplication, the set $\{1a, 2a, 3a, \dots, (p-1)a\}$ runs again through all nonzero residues,
  \[
  (1a)(2a)\dots((p-1)a) \equiv 1\cdot 2 \cdots (p-1) \pmod{p}
  \]
  and hence by dividing by $(p - 1)!$, we get $a^{p - 1} \equiv 1 \pmod{p}$.
\end{proof}

