n35936.content:
\begin{lemma}
  \label{ch35lemma1}
  Every nonzero polynomial $p(x) \in F[x_1, \dots, x_n]$ of degree $d$ has at
  most $dq^{n-1}$ roots in $F^n$.
\end{lemma}

n35938.content:
\begin{lemma}
  \label{ch35lemma2}
For every set $E \subseteq F^n$ of size $|E| < \binom{n+d}{d}$ there is a nonzero
polynomial $p(x) \in F[x_1, \dots, x_n]$ of degree at most $d$ that vanishes on $E$.
\end{lemma}

n35942.content:
\begin{lemma}
  \label{ch36lemma1}
  Any $(r \times n)$-Latin rectangle, $r < n$, can be extended to an $((r+1) \times n)$-Latin
  rectangle and hence can be completed to a Latin square.
\end{lemma}

n35944.content:
\begin{lemma}
  \label{ch36lemma2}
  Let $P$ be a partial Latin square of order $n$ with at most $n - 1$ cells filled and at
  most $\frac{n}{2}$ distinct elements, then $P$ can be completed to a Latin square of
  order $n$.
\end{lemma}

n35946.content:
\begin{theorem}[Smetaniuk's theorem]
  \label{smetaniuk_theorem}
  Any partial Latin square of order $n$ with at most $n - 1$ filled cells can be completed to a
  Latin square of the same order.
\end{theorem}

n35948.content:
\begin{theorem}
  \label{ch37theorem1}
  Let $M = (m_{ij})$ be an $n \times n$ matrix with entries in $\{0, 1\}$, and let $d_1, \dots, d_n$ be the row sums of $M$, that is, $d_i = \sum_{j=1}^{n} m_{ij}$. Then
\[
\operatorname{per} M \leq \prod_{i=1}^{n} (d_i!)^{1/d_i}.
\]
\end{theorem}

n35950.content:
\begin{theorem}
  \label{ch37theorem2}
  The number $L(n)$ of Latin squares of order $n$ is bounded by
  \[
  \frac{n!^{2n}}{n^{n^2}} \le L(n) \le \prod_{k=1}^{n}k!^{n/k}
  \]
\end{theorem}

n35958.content:
\begin{definition}
  \label{ch38definition1}
  Let $\vec{G} = (V, E)$ be a directed graph. A \textit{kernel} $K \subseteq V$ is a subset of the vertices such that
\begin{itemize}
    \item[(i)] $K$ is independent in $G$, and
    \item[(ii)] for every $u \notin K$ there exists a vertex $v \in K$ with an edge $u \rightarrow v$.
\end{itemize}
\end{definition}

n35959.content:
\begin{lemma}
  \label{ch38lemma1}
  \uses{ch38definition1}
  Let $\vec{G} = (V, E)$ be a directed graph, and suppose that for each vertex $v \in V$ we have
  a color set $C(v)$ that is larger than the outdegree, $|C(v)| \geq d^+(v) + 1$.
  If every induced subgraph of $\vec{G}$ possesses a kernel, then there exists a list coloring
  of $G$ with a color from $C(v)$ for each $v$.
\end{lemma}

n35961.content:
\begin{definition}
  \label{ch38definition2}
A matching $M$ of $G = (X \cup Y, E)$ is called \textit{stable} if the following condition holds:
Whenever $uv \in E \setminus M$, $u \in X$, $v \in Y$, then either $uy \in M$ with
$y > v$ in $N(u)$ or $xv \in M$ with $x > u$ in $N(v)$, or both.
\end{definition}

n35968.content:
\begin{theorem}
  \label{museum_guards}
  For any museum with $n$ walls, $\lfloor \frac{n}{3} \rfloor$ guards suffice.
\end{theorem}

