\begin{theorem}
  \label{ch42theorem}
  Whenever $T = \{v^{(1)}, \dots, v^{(m)}\}$ is an orthonormal representation of $G$ with constant $\sigma_T$, then
\[
\Theta(G) \leq \frac{1}{\sigma_T}.
\]
\end{theorem}

n35986.content:
\begin{theorem}[Gale's theorem]
  \label{gale_theorem}
  There is an arrangement of $2k + d$ points on $S^d$ such that every open hemisphere contains
  at least $k$ of these points.
\end{theorem}

n35990.content:
\begin{theorem}
  \label{borsuk_ulam}
  For every continuous map $f : S^d \to \mathbb{R}^d$ from $d$-sphere to $d$-space,
  there are antipodal points $x^*$, $-x^*$ that are mapped to the same point $f(x^*) = f(-x^*)$.
\end{theorem}

n35992.content:
\begin{theorem}
  \label{friendship}
  \lean{chapter44.friendship_theorem}
  \leanok
  Suppose that $G$ is a finite graph in which any two vertices have precisely one common neighbor.
  Then there is a vertex which is adjacent to all other vertices.
\end{theorem}

n35994.content:
