n35998.content:
\begin{theorem}
  \label{ch45theorem3}
For every $k \geq 2$, there exists a graph $G$ with chromatic number $\chi(G) > k$ and
girth $\gamma(G) > k$.
\end{theorem}

n36000.content:
\begin{theorem}
  \label{ch45theorem4}
  Let $G$ be a simple graph with $n$ vertices and $m$ edges, where $m \ge 4n$. Then
  \[
  \mycr(G) \ge \frac{1}{64}\frac{m^3}{n^2}.
  \]
\end{theorem}

n36045.type_full:
∀ (n : Nat) (hn : LE.le 1 n) (a : (Subtype fun x => Membership.mem (Finset.Icc 1 n) x) → Real),
  (∀ (i : Subtype fun x => Membership.mem (Finset.Icc 1 n) x), LT.lt 0 (a i)) →
    have harmonic := HDiv.hDiv (↑n) (Finset.univ.sum fun i => HDiv.hDiv 1 (a i));
    have geometric := HPow.hPow (Finset.univ.prod fun i => a i) (HDiv.hDiv 1 ↑n);
    have arithmetic := HDiv.hDiv (Finset.univ.sum fun i => a i) ↑n;
    have all_equal := ∀ (i : Subtype fun x => Membership.mem (Finset.Icc 1 n) x), Eq (a i) (a ⟨1, ⋯⟩);
    And (LE.le harmonic geometric)
      (And (LE.le geometric arithmetic)
        (And (Iff (Eq harmonic geometric) all_equal) (Iff (Eq geometric arithmetic) all_equal)))

